
import streamlit as st

from llm import generate_response
from prompt_templates import build_prompt


st.set_page_config(
    page_title="PromptLab AI",
    page_icon="🤖",
    layout="centered"
)

st.title("PromptLab AI")
st.subheader("Explore Prompt Engineering Techniques")

st.write(
    "Compare how different prompting methods influence "
    "the answers generated by an AI language model."
)

techniques = [
    "Zero-shot",
    "One-shot",
    "Few-shot",
    "CoT",
    "Manual CoT",
    "ToT"
]

technique = st.selectbox(
    "Choose a prompting method",
    techniques
)

task = st.text_area(
    "Enter your question or task",
    placeholder="Example: Explain how neural networks work."
)

with st.expander("Generation Settings"):
    temperature = st.slider(
        "Response creativity",
        min_value=0.0,
        max_value=1.0,
        value=0.3,
        step=0.1
    )

    max_tokens = st.slider(
        "Maximum response length",
        min_value=100,
        max_value=1000,
        value=500,
        step=100
    )

if st.button("Generate Answer", type="primary"):

    if not task.strip():
        st.warning("Please enter a question first.")

    else:
        try:
            prompt = build_prompt(technique, task)

            with st.expander("View Generated Prompt"):
                st.code(prompt, language="text")

            with st.spinner("Generating your answer..."):
                answer = generate_response(
                    prompt,
                    temperature,
                    max_tokens
                )

            st.subheader("AI Response")
            st.markdown(answer)

        except Exception as error:
            st.error(f"Unable to generate a response: {error}")